pous.declaration:
FUNCTION_BLOCK MovingAverage
VAR_INPUT
    cyclicExecution : BOOL;
    trigger : BOOL;
    value : LREAL;
    windowSize : INT;
    reset : BOOL;
END_VAR
VAR_OUTPUT
    average : LREAL;
    windowSizeReached : BOOL;
    error : BOOL;
    status : WORD;
END_VAR
VAR
    buffer : ARRAY[1..100] OF LREAL;
    head : INT := 0;
    count : INT := 0;
    sum : LREAL := 0.0;
    trigPrev : BOOL;
    trigRising : BOOL;
END_VAR

pous.implementation:
error := FALSE;
status := 0;
IF reset THEN
    head := 0;
    count := 0;
    sum := 0.0;
    average := 0.0;
    windowSizeReached := FALSE;
END_IF
IF windowSize < 1 OR windowSize > 100 THEN
    error := TRUE;
    status := 16#8200;
ELSE
    trigRising := trigger AND NOT trigPrev;
    trigPrev := trigger;
    IF cyclicExecution OR trigRising THEN
        IF count < windowSize THEN
            count := count + 1;
            head := count;
            buffer[head] := value;
            sum := sum + value;
        ELSE
            head := head + 1;
            IF head > windowSize THEN
                head := 1;
            END_IF
            sum := sum - buffer[head] + value;
            buffer[head] := value;
        END_IF
        windowSizeReached := (count >= windowSize);
        average := sum / INT_TO_LREAL(count);
    END_IF
END_IF
